package co.edu.uniquindio.poo.visual;

import co.edu.uniquindio.poo.controller.PrincipalController;
import co.edu.uniquindio.poo.model.*;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.*;
import javafx.collections.transformation.FilteredList;
import javafx.geometry.*;
import javafx.scene.Parent;
import javafx.scene.control.*;
import javafx.scene.layout.*;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.UUID;

/** Consola administrativa: vistas JavaFX sin lógica de negocio. */
public class VistaAdministrador {
    private final PrincipalController c;private final Administrador actor;
    private final ObservableList<Cliente> clientes=FXCollections.observableArrayList();private final ObservableList<Guia> guias=FXCollections.observableArrayList();private final ObservableList<IProductoTuristico> productos=FXCollections.observableArrayList();private final ObservableList<Reserva> reservas=FXCollections.observableArrayList();private final ObservableList<PropuestaPaquete> propuestas=FXCollections.observableArrayList();private final Label salida=new Label();private final Label clientesCount=new Label("0"),guiasCount=new Label("0"),productosCount=new Label("0"),pendientesCount=new Label("0");
    public VistaAdministrador(PrincipalController c,Administrador actor){this.c=c;this.actor=actor;}
    public Parent crearVista(){
        BorderPane root=new BorderPane();root.setPadding(new Insets(20));root.getStyleClass().add("page-background");Label title=new Label("Centro de operaciones");title.getStyleClass().add("section-title");Label sub=new Label("El equipo y las experiencias de RutaVerde, bajo control.");sub.getStyleClass().add("hero-copy");HBox metrics=new HBox(12,metric("CLIENTES",clientesCount,"metric-sage"),metric("GUÍAS",guiasCount,"metric-blue"),metric("EXPERIENCIAS",productosCount,"metric-green"),metric("POR REVISAR",pendientesCount,"metric-plum"));VBox header=new VBox(14,title,sub,metrics);header.getStyleClass().add("dashboard-hero");root.setTop(header);
        TabPane tabs=new TabPane();tabs.getTabs().addAll(tab("Clientes",vistaClientes()),tab("Guías",vistaGuias()),tab("Productos",vistaProductos()),tab("Reservas",vistaReserva()),tab("Propuestas",vistaPropuestas()),tab("Reportes",vistaReportes()));root.setCenter(tabs);salida.setWrapText(true);salida.getStyleClass().add("status-bar");HBox status=new HBox(new Label("ÚLTIMA ACCIÓN"),salida);HBox.setHgrow(salida,Priority.ALWAYS);status.getStyleClass().add("status-wrap");root.setBottom(status);refrescar();return root;
    }
    private VBox metric(String caption,Label value,String style){value.getStyleClass().add("metric-value");Label label=new Label(caption);label.getStyleClass().add("metric-caption");VBox card=new VBox(4,label,value);card.getStyleClass().addAll("metric-card",style);HBox.setHgrow(card,Priority.ALWAYS);return card;}
    private Tab tab(String name,Parent content){Tab t=new Tab(name,content);t.setClosable(false);return t;}
    private VBox panel(String title,String description,Parent content){Label h=new Label(title);h.getStyleClass().add("section-title");Label d=new Label(description);d.getStyleClass().add("muted");VBox v=new VBox(12,h,d,content);v.setPadding(new Insets(18));return v;}
    private Parent vistaClientes(){
        FilteredList<Cliente> filtrados=new FilteredList<>(clientes,p->true);TableView<Cliente> table=new TableView<>(filtrados);table.getColumns().setAll(List.of(col("Documento",Cliente::getIdentificacion),col("Nombre",Cliente::getNombreCompleto),col("País",x->x.getPaisOrigen().name()),col("Idioma",x->x.getIdiomaPreferido().name())));
        TextField search=new TextField();search.setPromptText("Buscar por documento, nombre o correo");search.textProperty().addListener((o,a,b)->filtrados.setPredicate(x->b==null||b.isBlank()|| (x.getIdentificacion()+" "+x.getNombreCompleto()+" "+x.getCorreo()).toLowerCase().contains(b.toLowerCase())));
        Button delete=new Button("Eliminar cliente seleccionado");delete.getStyleClass().add("secondary-button");delete.setOnAction(e->accion(()->{Cliente x=table.getSelectionModel().getSelectedItem();if(x==null)throw new IllegalArgumentException("Selecciona un cliente");c.eliminarUsuario(actor,x.getIdentificacion());refrescar();}));VBox find=new VBox(10,new Label("BUSCAR CLIENTE"),search,table,delete);find.getStyleClass().add("surface-card");
        TextField id=new TextField(),name=new TextField(),phone=new TextField(),email=new TextField(),pass=new PasswordField();id.setPromptText("Documento");name.setPromptText("Nombre completo");phone.setPromptText("Teléfono");email.setPromptText("Correo electrónico");pass.setPromptText("Contraseña inicial");ComboBox<Pais> country=new ComboBox<>(FXCollections.observableArrayList(Pais.values()));country.setPromptText("País de origen");ComboBox<Idioma> language=new ComboBox<>(FXCollections.observableArrayList(Idioma.values()));language.setPromptText("Idioma preferido");
        Button save=new Button("Ingresar cliente");save.getStyleClass().add("primary-button");save.setOnAction(e->accion(()->{c.registrarCliente(actor,id.getText(),name.getText(),phone.getText(),email.getText(),country.getValue(),language.getValue(),pass.getText());id.clear();name.clear();phone.clear();email.clear();pass.clear();refrescar();}));GridPane form=new GridPane();form.setHgap(10);form.setVgap(10);form.addRow(0,id,name);form.addRow(1,phone,email);form.addRow(2,country,language);form.add(pass,0,3);form.add(save,1,3);VBox add=new VBox(12,new Label("INGRESAR CLIENTE"),form,new Label("El administrador crea la cuenta; la clave inicial la define en el formulario."));add.getStyleClass().add("surface-card");
        TabPane sections=new TabPane(tab("Buscar cliente",find),tab("Ingresar cliente",add));return panel("Gestión de clientes","Busca una cuenta existente o registra una nueva desde una sección independiente.",sections);
    }
    private Parent vistaGuias(){
        FilteredList<Guia> filtrados=new FilteredList<>(guias,p->true);TableView<Guia> table=new TableView<>(filtrados);table.getColumns().setAll(List.of(col("Documento",Guia::getIdentificacion),col("Nombre",Guia::getNombreCompleto),col("Idiomas",x->x.getIdiomas().toString()),col("Tarifa diaria",x->"$"+x.getTarifaPorDia().toPlainString())));TextField search=new TextField();search.setPromptText("Buscar por documento, nombre o correo");search.textProperty().addListener((o,a,b)->filtrados.setPredicate(x->b==null||b.isBlank()||(x.getIdentificacion()+" "+x.getNombreCompleto()+" "+x.getCorreo()).toLowerCase().contains(b.toLowerCase())));
        Button delete=new Button("Eliminar guía seleccionado");delete.getStyleClass().add("secondary-button");delete.setOnAction(e->accion(()->{Guia x=table.getSelectionModel().getSelectedItem();if(x==null)throw new IllegalArgumentException("Selecciona un guía");c.eliminarUsuario(actor,x.getIdentificacion());refrescar();}));VBox find=new VBox(10,new Label("BUSCAR GUÍA"),search,table,delete);find.getStyleClass().add("surface-card");
        TextField id=new TextField(),name=new TextField(),phone=new TextField(),email=new TextField(),rate=new TextField(),pass=new PasswordField();id.setPromptText("Documento");name.setPromptText("Nombre completo");phone.setPromptText("Teléfono");email.setPromptText("Correo electrónico");rate.setPromptText("Tarifa diaria en pesos");pass.setPromptText("Contraseña inicial");ListView<Idioma> languages=new ListView<>(FXCollections.observableArrayList(Idioma.values()));languages.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);languages.setPrefHeight(110);Button save=new Button("Ingresar guía");save.getStyleClass().add("primary-button");save.setOnAction(e->accion(()->{c.registrarGuia(actor,id.getText(),name.getText(),phone.getText(),email.getText(),new HashSet<>(languages.getSelectionModel().getSelectedItems()),new BigDecimal(rate.getText()),pass.getText());refrescar();}));VBox add=new VBox(10,new Label("INGRESAR GUÍA"),new HBox(9,id,name),new HBox(9,phone,email),rate,pass,new Label("Idiomas que puede atender"),languages,save);add.getStyleClass().add("surface-card");TabPane sections=new TabPane(tab("Buscar guía",find),tab("Ingresar guía",add));return panel("Gestión del equipo","El administrador registra las cuentas del personal y define su tarifa diaria.",sections);
    }
    private Parent vistaProductos(){
        TextField code=new TextField(),name=new TextField(),hours=new TextField(),price=new TextField(),places=new TextField();code.setPromptText("Código de actividad");name.setPromptText("Nombre de experiencia");hours.setPromptText("Duración (horas)");price.setPromptText("Precio por persona");places.setPromptText("Cupos");ComboBox<MunicipioQuindio> town=new ComboBox<>(FXCollections.observableArrayList(MunicipioQuindio.values()));town.setPromptText("Municipio");ComboBox<Dificultad> difficulty=new ComboBox<>(FXCollections.observableArrayList(Dificultad.values()));difficulty.setPromptText("Dificultad");Button addActivity=new Button("Crear actividad");addActivity.getStyleClass().add("primary-button");addActivity.setOnAction(e->accion(()->{c.registrarActividad(actor,code.getText(),name.getText(),town.getValue(),Double.parseDouble(hours.getText()),Double.parseDouble(price.getText()),Integer.parseInt(places.getText()),difficulty.getValue());refrescar();}));
        TableView<IProductoTuristico> table=new TableView<>(productos);table.getColumns().setAll(List.of(col("Código",IProductoTuristico::obtenerCodigo),col("Experiencia o paquete",IProductoTuristico::obtenerNombre),col("Precio/persona",x->String.format("$%,.0f",x.obtenerPrecio())),col("Duración",x->x.obtenerDuracionHoras()+" h")));Button createPack=new Button("Crear paquete…");createPack.getStyleClass().add("secondary-button");createPack.setOnAction(e->dialogoPaquete());Button delete=new Button("Eliminar producto");delete.getStyleClass().add("secondary-button");delete.setOnAction(e->accion(()->{IProductoTuristico x=table.getSelectionModel().getSelectedItem();if(x==null)throw new IllegalArgumentException("Selecciona un producto");c.eliminarProducto(actor,x.obtenerCodigo());refrescar();}));VBox activity=new VBox(10,new Label("NUEVA ACTIVIDAD"),new HBox(9,code,name),new HBox(9,town,difficulty),new HBox(9,hours,price,places),addActivity);activity.getStyleClass().add("surface-card");return panel("Catálogo de experiencias","Los paquetes se construyen eligiendo las actividades que lo componen.",new VBox(14,activity,new HBox(10,new Label("CATÁLOGO"),createPack,delete),table));
    }
    private void dialogoPaquete(){
        Dialog<ButtonType> dialog=new Dialog<>();dialog.setTitle("Crear paquete turístico");dialog.setHeaderText("Elige qué experiencias hacen parte del paquete");TextField name=new TextField();name.setPromptText("Nombre del paquete");TextField discount=new TextField("0");discount.setPromptText("Descuento (0–20 %)");ListView<IProductoTuristico> choices=new ListView<>(FXCollections.observableArrayList(productos.stream().filter(p->!(p instanceof PaqueteTuristico)).toList()));choices.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);choices.setPrefHeight(220);choices.setCellFactory(v->new ListCell<>(){protected void updateItem(IProductoTuristico p,boolean empty){super.updateItem(p,empty);setText(empty||p==null?null:p.obtenerNombre()+" · "+String.format("$%,.0f",p.obtenerPrecio()));}});VBox box=new VBox(11,new Label("1 · Pon un nombre"),name,new Label("2 · Marca una o varias actividades"),choices,new Label("3 · Descuento opcional"),discount);box.setPadding(new Insets(12));dialog.getDialogPane().setContent(box);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,new ButtonType("Publicar paquete",ButtonBar.ButtonData.OK_DONE));dialog.showAndWait().ifPresent(result->{if(result.getButtonData()==ButtonBar.ButtonData.OK_DONE)accion(()->{if(choices.getSelectionModel().getSelectedItems().isEmpty())throw new IllegalArgumentException("Marca al menos una actividad");String code="PKG-"+UUID.randomUUID().toString().substring(0,6).toUpperCase(Locale.ROOT);c.registrarPaquete(actor,code,name.getText(),Double.parseDouble(discount.getText()),new ArrayList<>(choices.getSelectionModel().getSelectedItems()));salida.setText("Paquete "+code+" agregado al catálogo.");refrescar();});});
    }
    private Parent vistaReserva(){
        TableView<Reserva> table=new TableView<>(reservas);table.getColumns().setAll(List.of(col("Solicitud",r->"RV-"+r.getNumero()),col("Cliente",r->r.getCliente().getNombreCompleto()),col("Experiencia",r->r.getProducto().obtenerNombre()),col("Fecha del viaje",r->r.getFechaViaje().toString()),col("Viajeros",r->String.valueOf(r.getViajeros())),col("Estado",r->estadoReserva(r.getEstado()))));table.setPrefHeight(340);
        Label detail=new Label("Selecciona una solicitud para consultar sus datos.");detail.getStyleClass().add("product-detail");table.getSelectionModel().selectedItemProperty().addListener((o,a,r)->{if(r!=null)detail.setText("RV-"+r.getNumero()+"  ·  "+r.getProducto().obtenerNombre()+"  ·  "+detalleProducto(r.getProducto())+"  ·  "+r.getViajeros()+" viajero(s)  ·  total $"+r.calcularTotal()+"  ·  "+r.getFechaViaje());});
        Button approve=new Button("Validar pago y confirmar reserva");approve.getStyleClass().add("primary-button");Button reject=new Button("Rechazar solicitud");reject.getStyleClass().add("secondary-button");Label note=new Label("Solo las solicitudes pendientes se pueden aprobar. El cobro se procesa con la tarjeta enviada por el cliente.");note.getStyleClass().add("muted");
        approve.setOnAction(e->{Reserva r=table.getSelectionModel().getSelectedItem();if(r==null){salida.setText("Selecciona una solicitud.");return;}accion(()->{if(r.getEstado()!=EstadoReserva.PENDIENTE)throw new IllegalArgumentException("Selecciona una solicitud pendiente");ResultadoConfirmacion result=c.aprobarSolicitud(actor,r.getNumero());if(!result.exitoso())throw new IllegalStateException("No se confirmó: "+result.mensaje());salida.setText(result.voucher());refrescar();});});
        reject.setOnAction(e->{Reserva r=table.getSelectionModel().getSelectedItem();if(r==null){salida.setText("Selecciona una solicitud.");return;}accion(()->{c.rechazarSolicitud(actor,r.getNumero());refrescar();salida.setText("Solicitud rechazada; no se realizó ningún cobro.");});});
        VBox actions=new VBox(10,detail,note,new HBox(10,approve,reject));actions.getStyleClass().add("surface-card");return panel("Solicitudes y reservas","Revisa las solicitudes enviadas por clientes. Al aprobar, se valida el pago y queda confirmada la reserva.",new VBox(14,table,actions));
    }
    private Parent vistaPropuestas(){ListView<PropuestaPaquete> list=new ListView<>(propuestas);list.setPrefHeight(300);list.setCellFactory(v->new ListCell<>(){protected void updateItem(PropuestaPaquete p,boolean empty){super.updateItem(p,empty);setText(empty||p==null?null:p.getPaquete().obtenerNombre()+" · por "+p.getSolicitante().getNombreCompleto()+" · "+detalleProducto(p.getPaquete()));}});Button accept=new Button("Aprobar y publicar");accept.getStyleClass().add("primary-button");Button reject=new Button("Rechazar propuesta");Label status=new Label();accept.setOnAction(e->accion(()->{PropuestaPaquete p=list.getSelectionModel().getSelectedItem();if(p==null)throw new IllegalArgumentException("Selecciona una propuesta");c.aprobarPropuesta(actor,p.getCodigo());status.setText("Propuesta aprobada y paquete publicado.");refrescar();}));reject.setOnAction(e->accion(()->{PropuestaPaquete p=list.getSelectionModel().getSelectedItem();if(p==null)throw new IllegalArgumentException("Selecciona una propuesta");c.rechazarPropuesta(actor,p.getCodigo());status.setText("Propuesta rechazada.");refrescar();}));return panel("Ideas de paquetes de clientes","Revisa qué actividades incluye cada combinación y decide si se publica en el catálogo.",new VBox(12,list,new HBox(10,accept,reject),status));}
    private Parent vistaReportes(){DatePicker from=new DatePicker(LocalDate.now().withDayOfMonth(1)),to=new DatePicker(LocalDate.now());Label revenue=new Label(),popular=new Label();Button calculate=new Button("Generar reporte");calculate.getStyleClass().add("primary-button");calculate.setOnAction(e->accion(()->{revenue.setText("Ingresos de reservas confirmadas: $"+c.ingresos(actor,from.getValue(),to.getValue()));popular.setText("Producto con más viajeros en el periodo: "+c.reporteProductoMasPopular(actor,from.getValue(),to.getValue()).map(entry->entry.getKey().obtenerNombre()+" ("+entry.getValue()+" viajeros)").orElse("Sin reservas confirmadas"));}));VBox results=new VBox(12,revenue,popular);results.getStyleClass().add("report-results");return panel("Reportes de reservas confirmadas","El periodo se filtra por fecha del viaje; las solicitudes pendientes y rechazadas no cuentan.",new VBox(12,new HBox(10,new Label("Desde"),from,new Label("Hasta"),to,calculate),results));}
    private String detalleProducto(IProductoTuristico producto){return producto.listarActividades().stream().map(a->a.obtenerNombre()+" ("+a.getMunicipio().name()+")").reduce((a,b)->a+", "+b).orElse("Sin actividades");}
    private String estadoReserva(EstadoReserva estado){return switch(estado){case PENDIENTE->"Pendiente de aprobación";case CONFIRMADA->"Confirmada";case CANCELADA->"Cancelada";case RECHAZADA->"Rechazada";};}
    private <T> TableColumn<T,String> col(String title,java.util.function.Function<T,String> f){TableColumn<T,String> col=new TableColumn<>(title);col.setCellValueFactory(x->new SimpleStringProperty(f.apply(x.getValue())));col.setPrefWidth(170);return col;}
    private void accion(Runnable task){salida.setText("");try{task.run();if(salida.getText().isBlank())salida.setText("Operación realizada correctamente.");}catch(Exception ex){salida.setText("Error: "+ex.getMessage());new Alert(Alert.AlertType.ERROR,ex.getMessage(),ButtonType.OK).showAndWait();}}
    private void refrescar(){clientes.setAll(c.clientes(actor));guias.setAll(c.guias(actor));productos.setAll(c.productos());reservas.setAll(c.reservas(actor));propuestas.setAll(c.propuestasPendientes(actor));clientesCount.setText(String.valueOf(clientes.size()));guiasCount.setText(String.valueOf(guias.size()));productosCount.setText(String.valueOf(productos.size()));pendientesCount.setText(String.valueOf(reservas.stream().filter(r->r.getEstado()==EstadoReserva.PENDIENTE).count()));}
}


